///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.changePage
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver1 ver2 state
 * @returns
 * @hidden N
*/
scwin.changePage = async function (ver1, ver2, state) {
    /* sdd-asis-lifecycle:begin changePage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.preListForm || { elements: [] });

    if(form.page.value === '00'){	
        if(form.mode.value === 'new'){
            await $c.win.alert("모든 메뉴는 '기업개요'작성 이후에 작성이 가능합니다.");   
        }else{			
            if(state===''|| state==='30'||state==='35'||state==='37'){
                if(await $c.win.confirm('메뉴를 이동하면 저장 이후 수정된 내용은 반영되지 않습니다.\r\n이동하시겠습니까?')) await scwin.doChangePage(ver1,ver2);
            }else await scwin.doChangePage(ver1,ver2);
        }		
    }else{
        if(state===''|| state==='30'||state==='35'||state==='37'){
            if(await $c.win.confirm('메뉴를 이동하면 저장 이후 수정된 내용은 반영되지 않습니다.\r\n이동하시겠습니까?')) await scwin.doChangePage(ver1,ver2);
        }else await scwin.doChangePage(ver1,ver2);
    }

    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.doChangePage
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver1 ver2
 * @returns
 * @hidden N
*/
scwin.doChangePage = async function (ver1, ver2) {
    /* sdd-asis-lifecycle:begin doChangePage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.preListForm || { elements: [] });
    if(ver1 == 1 && ver2 == 1){
        form.action = '/listInvstg/listPrelmInvstg.do';
        form.method.value='';
        form.page.value='00';		
    }else if(ver1 == 1 && ver2 == 2){
        form.action = '/listInvstg/listPrelmInvstg.do';
        form.method.value='';
        form.page.value='01';
    }else if(ver1 == 1 && ver2 == 3){
        form.action = '/listInvstg/listPrelmInvstg.do';
        form.method.value='';
        form.page.value='02';
    }else if(ver1 == 1 && ver2 == 4){
        form.action = '/listInvstg/listPrelmInvstg.do';
        form.method.value='';
        form.page.value='03';
    }else if(ver1 == 1 && ver2 == 5){
        form.action = '/listInvstg/listPrelmInvstgEtc.do';
        form.method.value='prelistSearchEtc';
        form.page.value='6';
        form.bzCd.value='3_1';
    }else if(ver1 == 1 && ver2 == 6){
        form.action = '/listInvstg/listPrelmInvstgEtc.do';
        form.method.value='prelistSearchEtc';
        form.page.value='7';
        form.bzCd.value='3_1';
    }else if(ver1 == 1 && ver2 == 7){
        form.action = '/listInvstg/listPrelmInvstgEtc.do';
        form.method.value='prelistSearchEtc';
        form.page.value='8';
        form.bzCd.value='3_1';
    }else if(ver1 == 1 && ver2 == 8){
        form.action = '/listInvstg/listPrelmInvstgEtc.do';
        form.method.value='prelistSearchEtc';
        form.page.value='9';
        form.bzCd.value='3_1';
    }else if(ver1 == 1 && ver2 == 9){
        form.action = '/listInvstg/listPrePrtDepo.do';
        form.method.value='getlistPrePrtDepo';
        form.page.value='10';
        form.bzCd.value='3_1';
    }else if(ver1 == 1 && ver2 == 10){
        form.action = '/listInvstg/listPrelmInvstgEtc.do';
        form.method.value='prelistSearchEtc';
        form.page.value='5';
        form.bzCd.value='3_1';
    }else if(ver1 == 1 && ver2 == 11){
        form.action = '/listInvstg/listPrelmInvstgEtc.do';
        form.method.value='getMergeInfo';
        form.page.value='11';
        form.bzCd.value='3_1';
    }else if(ver1 == 4 && ver2 == 1){
        form.action = '/listInvstg/listPrePrtDepo.do';
        form.method.value='getlistPrePrtDepo';
        form.page.value='40';
        form.bzCd.value='3_1';
    }else if(ver1 == 2 && ver2 == 1){
        form.action = '/listInvstg/lplAttach.do';
        form.method.value='loadAttachForm';
        form.page.value='20';
        form.bzCd.value='3_1';
    }else if(ver1 == 3 && ver2 == 1){
        form.action = '/listInvstg/bbs.do';
        form.method.value = 'searchCommentLetterList';
        form.page.value = '30';
        form.bzCd.value = '3_1';
    }
    await moveUrl('/listInvstg/listPrePrtDepo.do', {});

    /* sdd-asis-lifecycle:end */
};
